"""Finalize first-draft documentation only after the observed full rerun passes."""
import json,re,subprocess
from records import ROOT,now,event

def run():
    observed=now();record='review/verification-submission-1.json'
    v=json.loads((ROOT/record).read_text());snap=json.loads((ROOT/'review/snapshot-submission-1.json').read_text())
    assert v['status']=='passed' and v['valid_as_final_submission_check'] and v['mode']=='all'
    assert len(v['document_checks'])==2
    claims=[json.loads(s) for s in (ROOT/'claims.jsonl').read_text().splitlines()]
    sources={r['source_id']:r for r in map(json.loads,(ROOT/'sources.jsonl').read_text().splitlines())}
    cited=re.findall(r'^- \*\*\[([^]]+)\]',(ROOT/'paper.md').read_text(),re.M)
    assert all(sources[s]['access']=='full_text_relevant_passages_checked' for s in cited)
    counts=dict(main_csv=len(v['table_checks']),supplemental_csv=sum(len(s['csv_checks']) for s in v['supplemental_checks']),
        main_raw=len(v['raw_array_checks']),supplemental_raw=sum(len(s['raw_array_checks']) for s in v['supplemental_checks']))
    summary=f"{counts['main_csv']} main and {counts['supplemental_csv']} supplemental CSV files; {counts['main_raw']} main and {counts['supplemental_raw']} supplemental raw-array files; exact paper/claim matches"
    p=ROOT/'VERIFY.md';s=p.read_text();start=s.index('Run on a copy');end=s.index('\n\n## Environment')
    s=s[:start]+f"Run on a copy of the submitted commit, with a fresh output directory outside the copy. The numerical procedure writes no source-file contents, makes no network request and calls no AI API. The final pre-submission full rerun passed: {summary}, in {v['elapsed_seconds']:.3f} seconds. Its unchanged original result is in {record}; source snapshot {snap['source_commit']} is identified in review/snapshot-submission-1.json. Later submission changes are documentation/receipts, with scientific files checked unchanged. The earlier preliminary check remains separately identified and is not substituted for this final check."+s[end:]
    s=s.replace('Frozen logistic conditions, including native-grid cases, reconstruct probabilities','Frozen and annually refreshed logistic conditions, including native-grid cases, reconstruct probabilities')
    s=s.replace('Regenerates CSV tables and standalone SVG/PNG figures; compares schema','Regenerates CSV tables and standalone SVG/PNG figures; compares CSV schema')
    s=s.replace('hypothetical reference errors and cohort context.','hypothetical reference errors, additional geography, higher-replication arable checks, projection derivatives and cohort context.')
    s=s.replace('This does not reduce trials, comparisons or numerical computation.','For reference-frame runs it checks each freshly written array before sharing, records its pre-sharing comparison, and checks the complete file layout. This bounds temporary storage. This does not reduce trials, comparisons or numerical computation.')
    s=s.replace('hardlinks immutable NPZ/NPY/PDF inputs only after matching their committed blob hashes','hardlinks immutable NPZ/NPY/PDF inputs plus frozen versioned data/scientific-result manifests, tables and raw-output metadata only after matching their committed blob hashes. Mutable ledgers, code, documents, figures and bookkeeping tallies are copied. Revisions must use new scientific destinations')
    s+='\nThe self-rerun uses the original dedicated full environment with the listed scientific-package versions. A fresh minimal package installation was not separately tested. Inspection of the verification import paths found no acquisition/geospatial/model-download dependency in the offline numerical procedure.\n'
    text="""\n\n## Claim checks and observed contributing computation times\n\nOpen each claim's listed evidence file and compare the fields in its `expected` object, then run the single entry point. The following are observed contributing-phase times in the final full rerun, not estimates for another computer. Shared phases appear under multiple claims; their times are not additive across rows. Model acquisition/refitting is outside these times.\n\n| Claim | Check | Contributing computation seconds |\n| --- | --- | --- |\n"""
    tasks={r['name']:r.get('elapsed_seconds',0) for r in v['supplemental_checks']}
    timing={r['path']:r['elapsed_seconds'] for r in v['timings']}
    main_time=sum(timing.get('results/inference/logistic-broad-'+r,0) for r in ['tessera','alphaearth'])
    mapping={'C01':main_time,'C02':main_time,'C03':main_time+sum(timing.get('results/inference/forest-broad-'+r,0) for r in ['tessera','alphaearth']),
        'C04':main_time,'C05':tasks.get('stable-arable',0),'C06':tasks.get('sparse',0),
        'C07':sum(value for name,value in tasks.items() if name.startswith('gradient-')),
        'C08':tasks.get('coherent-panel',0),'C09':tasks.get('census-comparison',0)+sum(value for name,value in timing.items() if 'census-inference' in name),
        'C10':sum(tasks.get(name,0) for name in ['additional-geography-arable','additional-arable-high-replication','covariance-context']),
        'C11':sum(value for name,value in tasks.items() if name.startswith('projection-derivative'))}
    for c in claims:text+=f"| {c['claim_id']} | {c['text']} See claims.jsonl for exact expected values and file paths. | {mapping[c['claim_id']]:.3f} |\n"
    text+='\nThe additional arable precision check keeps all estimates/SE/directions and regenerates its index arrays from documented NumPy seeds, shapes, dtypes and array-byte hashes. The original smaller-run index arrays remain bundled. Both simulations are on the same fixed references.\n'
    s+=text;p.write_text(s)
    p=ROOT/'README.md';s=p.read_text();start=s.index('Current state:');end=s.index('\n\n## Read',start)
    s=s[:start]+f"Current state: first draft prepared for the planned review by an AI agent. All planned and related exploratory analyses are complete; the additional cohort stopped at its preset resource cap. The final full offline self-rerun passed ({summary}). Consult tag submission-1 and events.jsonl for the submitted commit/time. No review result has yet been received. Once submission-1 is sealed, the directory is frozen until REVIEW-1."+s[end:]
    s=s.replace("this session's self-assessment, including pending work","this session's completed pre-submission self-assessment")
    s=s.replace('- final_report.md and the output SHA-256 manifest will be finalized before submission. Files and stages not yet present are not complete.',
        '- [review/verification-submission-1.json](review/verification-submission-1.json): passed final full self-rerun.\n- [final_report.md](final_report.md): results, failures, resource/intervention tallies and remaining limitations.\n- SHA256SUMS.json: scoped inventory including raw files excluded from Git; exclusions and terminal receipts are explicit.')
    s=s.replace('| results/reference-sensitivity/, description-main/ |','| data/validation-cohort-v1.json, results/additional-geography*/ | Separate exploratory geography, original points and full/arable references |\n| results/additional-arable-high-replication/, covariance-context/ | Higher-precision simulation and known-population influence context |\n| results/projection-derivative/, validation-projection-derivative/ | Original and local-derivative intervals, saved controls and local numerical validation |\n| results/reference-sensitivity/, description-main/, description-final/ |')
    s+='\nThe scoped SHA inventory includes all retained scientific raw data, including duplicate self-rerun paths omitted from Git. Only Git internals, dependency environments/caches, bytecode and the current inventory are excluded. Later mirror/check/commit receipts are outside the inventory. events.jsonl uses an explicit byte-prefix hash so terminal commit IDs can be appended without claiming a self-referential whole-file hash.\n'
    p.write_text(s)
    rows=[
      ('Close prior work','Repeated close searches and full-text checks are indexed in sources.jsonl and the saved final search bundles. Recent crop-map fitness, annual-embedding transfer, permanent/rotating sampling, entropy, prediction-powered inference and projection derivatives are covered. Search-only blocked/unresolved leads are not supporting citations. No absence-of-prior-work or new-estimator/theorem claim.'),
      ('Citations',f'All {len(cited)} supporting references have relevant full-text passages checked. Rendering enforces that status. The Agricultural Cultivated Areas name and intended-use limitation were rechecked against the source paper.'),
      ('Readability','Introduction gives agricultural monitoring background before technical details. Published group/administrative names are retained; biological species diversity, realized harvest and ecological/policy effects are separate. The abstract leads with planned outcomes and identifies later results as exploratory.'),
      ('Claim scope','The main precision/coverage/direction comparison concerns the original fixed cohort and interval rule. Additional arable precision reversal and projection propagation explicitly qualify it. Coverage and wrong-direction reporting are kept distinct. No universal panel preference or calibrated local-projection interval is claimed.'),
      ('Signal and trivial cases','The no-change point baseline appears early and in the common-scale budget figure. It is not an interval or evidence of no change. Tiny/zero/unchanged/floor/single-group and identical/constant-prediction cases are retained and counted. Identical direct controls are counted once.'),
      ('Support and geography','Complete-support original checks remove the embedding-mask/finite-point alternative. Original and additional stable-arable populations have different support, composition and signal; no causal grassland/rotation attribution. Additional acquisition order/eligibility was fixed before outcomes and the attained cohort committed before inference.'),
      ('Stronger comparisons','Fine hierarchy, secondary years, forests and annually refreshed logistic controls are complete. Refreshed source-year coefficients exactly matched original controls; extra annual training labels are not audit-budget matched. All favorable/unfavorable jackknife, weighting, strata and hard-auxiliary outcomes remain.'),
      ('Projection and interval mechanism','Original rules, all gradient floors and the established local projection derivative are compared at unchanged point estimates. Local finite differences and a nonregular boundary fixture distinguish software correctness from calibration. Both original and local-rule raw outputs remain for all heads.'),
      ('Simulation precision','The additional arable boundary is retained with both original and higher-replication results. Monte Carlo SE concerns these fixed references, not geographic population uncertainty. Known-population covariance proxies are not exact entropy variances.'),
      ('Coherent monitoring','A four-year coherent panel checks marginal/joint coverage and any report/error. Bonferroni widening is not claimed to repair invalid marginal intervals; a single retention rate is not optimized into a prescription.'),
      ('Reference and geometry limits','Second-decoder, point/native-grid, full-support, hypothetical reference-error and offset checks were examined as alternatives using saved/public data. They establish consistency/sensitivity, not independently observed harvest or field registration. No stronger external truth was obtained; impossibility of obtaining one is not asserted.'),
      ('Training and total reference information','Test regions are held out only from downstream fitting; foundation pretraining exposure is unresolved. Source training/calibration and the retrospective five-year eligibility frame are outside audit-label budgets. Field visits, clustered parcel annotation and user/policy outcomes were not evaluated.'),
      ('Numbers and reproduction',f'Final pre-submission full rerun: passed. {summary}. Observed runtime {v["elapsed_seconds"]:.3f}s; source {snap["source_commit"]}. This is a rerun by this session, not independent reproduction. Original default500 outputs remained unchanged after parameterization; all new conditions were included.'),
      ('Storage and process limits','The short unwrapped diagnostic briefly exceeded two processes and lacked its runner timeout; retained retrospectively. A formatting run once recorded a stale code commit and was corrected/rerun. Automatic Git packing peak was unmeasured, so a transient storage breach cannot be ruled out. Subsequent GC is disabled per commit; final checks record allocated blocks and payload separately.'),
      ('Interventions and key','Human-confirmed usage-limit resumes, including the second endpoint uncertainty, are recorded. The only other-model generation was the mandatory topic critique. No unplanned human scientific advice, participants, subagents, external contact/publication or new billing route. Exact-value key scans are required before commit/sealing and recorded without exposing the value.'),
      ('Remaining weaknesses','Convenience geography, fixed references/fitted maps, declared intent, eligibility information outside budget, numerical/nonregular interval behavior and unmeasured external validity remain explicit. More replications/control heads and saved-data/support checks were used where feasible; they do not remove these external limitations.')]
    text=f'# Pre-submission self-check\n\nCompleted documentation observed {observed}. This is self-assessment, not review by another agent or independent reproduction.\n\n| Check | Evidence and disposition |\n| --- | --- |\n'
    for name,body in rows:text+=f'| {name} | {body} |\n'
    (ROOT/'review/self-check.md').write_text(text)
    event('self_check_completed','Finish citation, scope, alternative-explanation and observed full-rerun checks',['review/self-check.md','VERIFY.md','README.md',record],verified_source_commit=snap['source_commit'])
    print(json.dumps(dict(observed_at_utc=observed,cited_full_text_sources=len(cited),claims=len(claims),verification_counts=counts)))

if __name__=='__main__':run()
